document.querySelectorAll('[data-lab="G05-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready="true";const sel=root.querySelector("[data-state]"),en=root.dataset.lang==="en";function update(){const s=sel.value;root.querySelector("[data-he]").style.display=s==="HID"?"none":"";root.querySelector("[data-hd]").style.display=s==="HIE"?"none":"";root.querySelector("[data-charge]").textContent=(en?"Charge: ":"电荷：")+(s==="HIP"?"+1e":"0e");const t={HIE:en?"H on NE2 (HE2); ND1 has no ring proton. Neutral tautomer selected for His68.":"NE2带氢HE2，ND1不带环上氢。His68采用这一中性互变异构体。",HID:en?"H on ND1 (HD1); NE2 has no ring proton. Net charge remains zero, while donor/acceptor positions change.":"ND1带氢HD1，NE2不带环上氢。净电荷仍为零，氢键供受体位置发生改变。",HIP:en?"Both nitrogen sites carry protons. The side-chain formal charge is +1e.":"两个环氮都带氢，侧链形式电荷为+1e。"};root.querySelector("[data-readout]").textContent=t[s];}sel.addEventListener("change",update);root.querySelector("[data-reset]").addEventListener("click",()=>{sel.value="HIE";update();});update();});